 const preview=document.querySelector<HTMLElement>('.device-preview')!,sizeInput=document.querySelector<HTMLInputElement>('[data-control-size]')!,opacityInput=document.querySelector<HTMLInputElement>('[data-control-opacity]')!,sizeOutput=document.querySelector<HTMLOutputElement>('[data-size-output]')!,opacityOutput=document.querySelector<HTMLOutputElement>('[data-opacity-output]')!,selectedLabel=document.querySelector<HTMLElement>('[data-selected-label]')!;
 const selectControl=(id:ControlId)=>{selectedControl=id;document.querySelectorAll<HTMLElement>('[data-control],[data-control-row]').forEach(el=>el.classList.toggle('selected',(el.dataset.control||el.dataset.controlRow)===id));selectedLabel.textContent=controlMeta.find(item=>item.id===id)!.label;sizeInput.value=String(points[id].size*100);opacityInput.value=String(points[id].opacity*100);sizeOutput.value=`${Math.round(points[id].size*100)}%`;opacityOutput.value=`${Math.round(points[id].opacity*100)}%`};
