function toggleRunLoadout(force?:boolean){const panel=document.querySelector<HTMLElement>('#run-loadout'),toggle=document.querySelector<HTMLElement>('#loadout-toggle');if(!panel)return;const expanded=force??panel.classList.contains('collapsed');panel.classList.toggle('collapsed',!expanded);toggle?.setAttribute('aria-expanded',String(expanded));toggle?.setAttribute('aria-label',expanded?'Minimize run loadout':'Show run loadout')}
function updateRunLoadout(loadout:{stigmata:any[];classes:any[];perks?:any[];weapons?:any[]}){const signature=JSON.stringify(loadout);if(signature===loadoutSignature)return;loadoutSignature=signature;const render=(items:any[],id:string,countId:string)=>{setText(countId,`${items.length} / 5`);const target=document.getElementById(id);if(!target)return;target.innerHTML=Array.from({length:5},(_,index)=>{const item=items[index];if(!item)return '<div class="loadout-slot empty" aria-label="Empty card slot"><i>+</i><small>EMPTY</small></div>';const pips=Array.from({length:3},(_,star)=>star<item.stars?'◆':'◇').join('');return `<div class="loadout-slot filled" style="--slot-color:${cardHue(item.tag)}" title="${item.name}, ${item.stars} stars"><i>${cardIcon(item.tag)}</i><b>${item.name}</b><small>${pips}</small></div>`}).join('')};const compact=(items:any[],id:string)=>{const target=document.getElementById(id);if(!target)return;target.innerHTML=items.map(item=>`<div class="loadout-chip" style="--slot-color:${item.color||cardHue(item.tag)}" title="${item.name}, level ${item.stars}"><i>${cardIcon(item.tag)}</i><b>${item.name}</b><small>${item.stars}</small></div>`).join('')};render(loadout.stigmata,'stigmata-slots','stigmata-count');render(loadout.classes,'class-slots','class-count');compact(loadout.weapons||[],'weapon-slots');compact(loadout.perks||[],'perk-slots');const radar=document.getElementById('upgrade-radar');if(radar){const active=[...(loadout.weapons||[]),...(loadout.perks||[]),...loadout.stigmata,...loadout.classes].slice(0,8);radar.innerHTML=active.map(item=>`<span style="--effect-color:${item.color||cardHue(item.tag)}" title="${item.name} · level ${item.stars}"><i>${cardIcon(item.tag)}</i><b>${item.stars}</b></span>`).join('');radar.classList.toggle('show',active.length>0)}}
