function updateHud(s:any){const pct=(s.hp/s.maxHp*100),pulse=(id:string,cls='hud-pop')=>{const el=document.getElementById(id);if(!el)return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls)};setText('hp-text',`${Math.ceil(s.hp)} / ${Math.round(s.maxHp)}`);setWidth('hp-fill',pct);setText('timer',formatTime(s.time));setText('phase',s.bossPaused?`BOSS · ${stages[selectedStage].endless?'CYCLE':'PHASE'} ${s.phase}`:stages[selectedStage].endless?`CYCLE ${s.phase}`:`PHASE ${s.phase}`);setWidth('phase-fill',stages[selectedStage].endless?(s.time%120)/120*100:s.time/540*100);setText('level',s.level);setWidth('xp-fill',s.xp/s.xpNext*100);setText('dash-count',s.dash);setText('kills',s.kills);setText('run-coins',s.coins);if(s.level>lastHud.level)pulse('level','level-pop');if(s.coins>lastHud.coins)pulse('run-coins');if(s.kills>lastHud.kills)pulse('kills');if(s.dash>lastHud.dash)pulse('dash-count');const dash=document.querySelector<HTMLElement>('#dash'),dashCool=dash?.querySelector<HTMLElement>('i');if(dash&&dashCool){const remaining=Math.max(0,s.dashProgress),ratio=s.dashMax?remaining/s.dashMax:0;dashCool.style.setProperty('--cool',`${Math.min(1,ratio)*360}deg`);dash.classList.toggle('recharging',remaining>0);dash.classList.toggle('empty',s.dash===0);dash.setAttribute('aria-label',remaining>0?`Dash: ${s.dash} charges, next charge in ${remaining.toFixed(1)} seconds`:`Dash: ${s.dash} charges ready`)}const skillButton=document.querySelector<HTMLElement>('#skill'),skillRing=skillButton?.querySelector<HTMLElement>('i'),skillTime=document.querySelector<HTMLOutputElement>('#skill-cooldown'),ready=s.skill<=0;if(skillButton&&skillRing&&skillTime){const remaining=Math.max(0,s.skill),ratio=s.skillMax?remaining/s.skillMax:0;skillRing.style.setProperty('--cool',`${Math.min(1,ratio)*360}deg`);skillTime.textContent=remaining>0?(remaining<10?remaining.toFixed(1):String(Math.ceil(remaining))):'';skillButton.classList.toggle('recharging',remaining>0);skillButton.classList.toggle('ready',ready);if(ready&&!lastHud.skillReady){skillButton.classList.remove('just-ready');void skillButton.offsetWidth;skillButton.classList.add('just-ready')}skillButton.setAttribute('aria-label',remaining>0?`Skill ready in ${remaining.toFixed(1)} seconds`:'Skill ready')}const bh=document.querySelector<HTMLElement>('#boss-hp');if(bh){bh.classList.toggle('show',!!s.boss);const fill=bh.querySelector<HTMLElement>('i');if(fill&&s.boss)fill.style.width=`${Math.max(0,s.boss.hp/s.boss.maxHp*100)}%`}updateBossPointers(s.bossMarkers||[]);document.querySelector('#game-host')?.classList.toggle('low-hp',pct<30);lastHud={level:s.level,coins:s.coins,kills:s.kills,skillReady:ready,dash:s.dash}}
function updateBossPointers(markers:any[]){const layer=document.querySelector<HTMLElement>('#boss-pointer-layer');if(!layer)return;while(layer.children.length<markers.length){const marker=document.createElement('div');marker.className='boss-pointer';marker.innerHTML='<i>▲</i><b></b><small></small>';layer.appendChild(marker)}Array.from(layer.children).forEach((node,index)=>{const el=node as HTMLElement,data=markers[index];el.classList.toggle('show',!!data);if(!data)return;el.style.left=`${data.x}%`;el.style.top=`${data.y}%`;el.style.setProperty('--angle',`${data.angle}deg`);el.style.setProperty('--boss-color',data.color);el.querySelector('b')!.textContent=data.name;el.querySelector('small')!.textContent=`${Math.round(data.distance)}m`;el.setAttribute('aria-label',`${data.name}, ${Math.round(data.distance)} meters away`)})}
const setText=(id:string,v:any)=>{const e=document.getElementById(id);if(e)e.textContent=String(v)};const setWidth=(id:string,v:number)=>{const e=document.getElementById(id);if(e)e.style.width=`${Math.max(0,Math.min(100,v))}%`};
