function showUpgradeFeedback(card:any){const layer=document.querySelector<HTMLElement>('#upgrade-toast-layer');if(!layer)return;const level=card.kind==='weapon-upgrade'?game?.getWeaponStar(card.id)||1:card.kind==='weapon'?1:game?.getUpgrade(card.id)||1,color=card.color||cardHue(card.tag),toast=document.createElement('div');toast.className='upgrade-toast';toast.style.setProperty('--upgrade-color',color);toast.innerHTML=`<i>${cardIcon(card.tag)}</i><span><small>${card.kind==='weapon'?'ARMAMENT ONLINE':'ADAPTATION ACQUIRED'}</small><b>${card.name}</b><em>LEVEL ${level}</em></span>`;layer.replaceChildren(toast);const host=document.querySelector<HTMLElement>('#game-host');host?.classList.remove('upgrade-acquired');if(host){host.style.setProperty('--upgrade-color',color);void host.offsetWidth;host.classList.add('upgrade-acquired')}setTimeout(()=>toast.classList.add('leaving'),1850);setTimeout(()=>{toast.remove();host?.classList.remove('upgrade-acquired')},2350)}

function cardPool(){const all=[...relics.map(x=>({...x,kind:'relic'})),...classes.map(x=>({...x,kind:'class'})),...perks.map(x=>({...x,kind:'perk',description:x.effects[Math.min(2,game?.getUpgrade(x.id)||0)]}))];return all.filter(x=>(game?.getUpgrade(x.id)||0)<3&&(game?.canOfferUpgrade(x.id,x.kind)??true))}
function weaponPool(){const starting=characters.find(c=>c.id===save.selectedCharacter)?.weapon;return weapons.filter(w=>w.id!==starting).map(w=>({...w,kind:'weapon',tag:'SECOND WEAPON',description:`${w.type} · ${w.damage} damage · ${w.fireRate}/s fire rate · built-in ${w.perk}`}))}
function weaponUpgradePool(){return(game?.getEquippedWeapons()||[]).filter((w:any)=>(game?.getWeaponStar(w.id)||1)<3).map((w:any)=>{const current=game?.getWeaponStar(w.id)||1,next=current+1,description=next===2?`Calibrate to 2★: +20% damage, +10% fire rate, +8% projectile speed and rank 2 ${w.perk}.`:`Overdrive to 3★: +40% damage, +20% fire rate and projectile speed, and rank 3 ${w.perk}.`;return{...w,kind:'weapon-upgrade',tag:'ARMAMENT',currentStar:current,description}})}
function cardOfferWeight(card:any){
 const owned=game?.getUpgrade(card.id)||0,weaponsInUse=game?.getEquippedWeapons()||[],character=characters.find(c=>c.id===save.selectedCharacter),statuses=new Set(weaponsInUse.map((weapon:any)=>weapon.status).filter(Boolean));
 if(character?.id==='mira')statuses.add('ignite');if(character?.id==='juno')statuses.add('chill');if(character?.id==='kade')statuses.add('mark');
 const statusEffects:Record<string,string>={igniteDamage:'ignite',chillStrength:'chill',markDamage:'mark'},statusEffect=statusEffects[String(card.effect)],damageType=card.effect==='physicalDamage'?'physical':card.effect==='elementalDamage'?'elemental':undefined,typeRelevant=!damageType||weaponsInUse.some((weapon:any)=>weapon.type===damageType),statusRelevant=!statusEffect||statuses.has(statusEffect);
 // Upgrades remain attainable, while build-specific cards are more likely to
 // appear without making off-build experimentation impossible.
 return(owned?1.35+owned*.2:1)*(typeRelevant?1.2:.55)*(statusRelevant?1.25:.4)*(card.kind==='perk'?1.12:1);
}
function takeWeighted(choices:any[],filter:(card:any)=>boolean=()=>true){const candidates=choices.map((card,index)=>({card,index,weight:filter(card)?cardOfferWeight(card):0})).filter(entry=>entry.weight>0);if(!candidates.length)return;let roll=Math.random()*candidates.reduce((sum,entry)=>sum+entry.weight,0),picked=candidates[candidates.length-1];for(const entry of candidates){roll-=entry.weight;if(roll<=0){picked=entry;break}}return choices.splice(picked.index,1)[0]}
function drawCards(pool:any[]=cardPool(),count=5){
 const choices=[...pool],out:any[]=[];
 // Every normal draft represents all three upgrade families when available.
 for(const kind of ['perk','relic','class']){const card=takeWeighted(choices,candidate=>candidate.kind===kind);if(card)out.push(card)}
 while(out.length<count&&choices.length){const diverse=choices.filter(card=>!out.some(chosen=>card.effect&&chosen.effect===card.effect)&&!(card.tags?.includes('Penalty')&&out.some(chosen=>chosen.tags?.includes('Penalty')))),card=takeWeighted(choices,candidate=>!diverse.length||diverse.includes(candidate));if(!card)break;out.push(card)}
 return out.sort(()=>Math.random()-.5)
}
function cardTags(card:any){return card.tags?.length?card.tags:[card.tag]}
function tierValue(card:any,index:number){return `${card.values[index]}${card.unit||'%'}`}
function cardEffectCopy(card:any,index:number){if(!card.values)return card.description;const value=tierValue(card,index),copy:{[key:string]:string}={regen:`Regenerate ${value} every second.`,dashRecharge:`Reduce dash recharge time by ${value}.`,physicalDamage:`Increase physical damage by ${value}.`,elementalDamage:`Increase elemental damage by ${value}.`,markDamage:`Increase Mark detonation damage by ${value}.`,coinGain:`Increase run-coin drops by ${value}.`,damageReduction:`Reduce incoming damage by ${value}.`,fireRate:`Increase weapon fire rate by ${value}.`,moveSpeed:`Increase movement speed by ${value}.`,maxHp:`Increase maximum health by ${value}.`,critRate:`Increase critical-hit chance by ${value}.`,critDamage:`Increase critical-hit damage by ${value}.`,igniteDamage:`Increase Ignite damage by ${value}.`,chillStrength:`Increase Chill slowing strength by ${value}.`,bossDamage:`Increase damage against bosses by ${value}.`,totalDamage:`Increase all damage by ${value}.`,skillCooldown:`Reduce active-skill cooldown by ${value}.`,riskDamage:`Increase all damage by ${value}.`,auraDamage:`Deal ${value} to nearby enemies each second.`,revive:`Revive once per run with ${value}.`,stationaryDamage:`Increase damage by ${value} while standing still.`,missingHpDamage:`Gain up to ${value} damage as health falls.`,skillDamage:`Increase active-skill damage by ${value}.`,statusDamage:`Increase status-effect damage by ${value}.`,bulletSpeed:`Increase projectile speed and range by ${value}.`,xpGain:`Increase experience gained by ${value}.`};const penalty=card.penaltyValues?` Take ${card.penaltyValues[index]}% more damage.`:'';return `${copy[card.effect]||`${card.description} ${value}.`}${penalty}`}
function renderUpgradeCard(card:any,index:number,selected:boolean){const current=card.kind==='weapon-upgrade'?(card.currentStar??game?.getWeaponStar(card.id)??1):(game?.getUpgrade(card.id)||0),tierIndex=Math.min(2,current),next=card.kind==='weapon-upgrade'?Math.min(3,current+1):current+1,tags=cardTags(card),effect=cardEffectCopy(card,tierIndex),kindLabel=card.kind.toUpperCase().replace('-',' ');return `<button class="upgrade-card ${selected?'selected':''}" data-card="${index}" style="--h:${cardHue(card.tag)}"><div class="card-index">0${index+1}</div><div class="card-summary"><div class="card-icon">${cardIcon(card.tag)}</div><small>${kindLabel}</small><h3>${card.name}</h3><div class="tag-row">${tags.map((tag:string)=>`<span class="tag">${tag}</span>`).join('')}</div>${stars(next,3)}</div><div class="card-detail"><small>${kindLabel} // ${next}★</small><h3>${card.name}</h3><div class="tag-row">${tags.map((tag:string)=>`<span class="tag">${tag}</span>`).join('')}</div><p>${effect}</p></div></button>`}
function showCards(level:number){
 selectedCard=null;
 const secondWeaponDraft=level===5&&!game?.getHasSecond(),upgradeChoices=weaponUpgradePool(),weaponUpgradeDraft=level>=10&&level%5===0&&upgradeChoices.length>0,fixedDraft=weaponUpgradeDraft;
 const cards=secondWeaponDraft?drawCards(weaponPool(),3):weaponUpgradeDraft?upgradeChoices:drawCards(),cost=refreshes<2?0:25+(refreshes-2)*25;
 const mode=secondWeaponDraft?'SECONDARY ARMAMENT':weaponUpgradeDraft?'ARMAMENT CALIBRATION':'FIELD ADAPTATION',title=secondWeaponDraft?'CHOOSE A SECOND WEAPON':weaponUpgradeDraft?'UPGRADE AN EQUIPPED WEAPON':'CHOOSE ONE UPGRADE';
 const host=document.querySelector('#game-host')!;
 host.insertAdjacentHTML('beforeend',`<section class="card-screen ${secondWeaponDraft?'weapon-draft':''} ${weaponUpgradeDraft?'weapon-upgrade-draft':''}" id="card-screen"><header><small>LEVEL ${level} // ${mode}</small><h2>${title}</h2><b class="card-countdown" aria-label="Time remaining">25</b><b class="run-balance">◈ ${game?.getCoins()||0} RUN COINS</b></header><div class="card-grid"></div><footer><button data-skip>SKIP</button><button data-refresh ${fixedDraft?'hidden':''} ${(game?.getCoins()||0)<cost?'disabled':''}>REFRESH <small>${cost===0?'FREE':`◈ ${cost}`}</small></button><button class="confirm" data-confirm disabled>CONFIRM</button></footer></section>`);
 const screen=document.querySelector('#card-screen')!,grid=screen.querySelector('.card-grid')!,countdown=screen.querySelector('.card-countdown')!;let remaining=25,closed=false;
 const close=(action:'confirm'|'skip'|'refresh')=>{if(closed)return;closed=true;clearInterval(timer);if(action==='confirm'&&selectedCard){const chosen=selectedCard;game?.applyCard(chosen.id,chosen.kind);screen.remove();requestAnimationFrame(()=>showUpgradeFeedback(chosen));return}else if(action==='refresh'&&!fixedDraft){if(game?.spendCoins(cost)){refreshes++;screen.remove();showCards(level);return}closed=false;return}else game?.resume();screen.remove()};
 const timer=window.setInterval(()=>{remaining--;countdown.textContent=String(Math.max(0,remaining));countdown.classList.toggle('urgent',remaining<=5);if(remaining<=0)close(selectedCard?'confirm':'skip')},1000);
 const render=()=>{grid.innerHTML=cards.map((card,i)=>renderUpgradeCard(card,i,selectedCard===card)).join('');grid.querySelectorAll<HTMLElement>('[data-card]').forEach(el=>el.onclick=()=>{selectedCard=cards[+el.dataset.card!];(screen.querySelector('[data-confirm]') as HTMLButtonElement).disabled=false;render()})};
 render();screen.querySelector('[data-confirm]')?.addEventListener('click',()=>close('confirm'));screen.querySelector('[data-skip]')?.addEventListener('click',()=>close('skip'));screen.querySelector('[data-refresh]')?.addEventListener('click',()=>close('refresh'))
}
function cardHue(tag:string){return {'Survival':'#74d7a2','Mobility':'#62d9eb','DMG Boost':'#ffbd55','Elemental':'#ff775d','Debuff':'#c78cff','SECOND WEAPON':'#efff9a','ARMAMENT':'#79ddff'}[tag]||'#e85e69'}function cardIcon(tag:string){return {'Survival':'♥','Mobility':'➤','DMG Boost':'✹','Elemental':'◆','Debuff':'⌁','SECOND WEAPON':'⌖','ARMAMENT':'⬆'}[tag]||'✦'}
function showResults(stats:RunStats){const c=characters.find(x=>x.id===save.selectedCharacter)!,hasNext=stats.victory&&!stages[stats.stage].endless&&stats.stage<stages.length-1,nextStage=stats.stage+1;save.characterExp[c.id]=(save.characterExp[c.id]||0)+stats.xp;if(stats.victory&&!stages[stats.stage].endless)save.bestStage=Math.min(5,Math.max(save.bestStage,nextStage));if(stages[stats.stage].endless)save.endlessTime=Math.max(save.endlessTime,stats.time);writeSave(save);shell(`<main class="results"><div class="result-sigil ${stats.victory?'win':'loss'}">${stats.victory?'◇':'×'}</div><small>${stats.victory?'BREACH SEALED':'SIGNAL LOST'}</small><h2>${stats.victory?'OPERATION COMPLETE':'RUN TERMINATED'}</h2><p>${stages[stats.stage].name}</p><div class="result-stats"><span><small>SURVIVED</small><b>${formatTime(stats.time)}</b></span><span><small>ELIMINATIONS</small><b>${stats.kills}</b></span><span><small>RUN COINS LEFT</small><b>${stats.coins}</b></span><span><small>OPERATIVE EXP</small><b>+${stats.xp}</b></span></div><div class="progress-report"><span>${c.name} ${stars(starCount(save.characterExp[c.id]))}</span><div class="xp-track"><i style="width:${Math.min(100,(save.characterExp[c.id]/10000)*100)}%"></i></div></div><div class="result-actions">${hasNext?`<button class="next-stage" data-next>NEXT STAGE <small>${stages[nextStage].name}</small></button>`:''}<button class="result-menu" data-menu>MAIN MENU</button></div></main>`,'result-screen');document.querySelector('[data-menu]')?.addEventListener('click',showMenu);document.querySelector('[data-next]')?.addEventListener('click',()=>startGame(nextStage))}
function formatTime(t:number){const m=Math.floor(t/60),s=Math.floor(t%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
showMenu();

function showObjectives(){syncAchievements();const achievementCards=achievements.map(a=>{const value=careerProgress(a.stat),done=save.unlockedAchievements.includes(a.id),pct=Math.min(100,value/a.target*100);return `<article class="objective-card ${done?'complete':''}"><i>${done?'✓':'◇'}</i><div><small>ACHIEVEMENT</small><h3>${a.name}</h3><p>${a.description}</p><div class="objective-progress"><span style="width:${pct}%"></span></div><em>${progressLabel(a.stat,value,a.target)}</em></div><b>+${a.reward}</b></article>`}).join('');const challengeCards=challenges.map(c=>{const value=careerProgress(c.stat),ready=value>=c.target,claimed=save.claimedChallenges.includes(c.id),pct=Math.min(100,value/c.target*100);return `<article class="objective-card challenge ${claimed?'complete':''}"><i>${claimed?'✓':'!'}</i><div><small>CHALLENGE</small><h3>${c.name}</h3><p>${c.description}</p><div class="objective-progress"><span style="width:${pct}%"></span></div><em>${progressLabel(c.stat,value,c.target)}</em></div><button data-claim="${c.id}" ${!ready||claimed?'disabled':''}>${claimed?'CLAIMED':ready?'CLAIM':'+'+c.reward}</button></article>`}).join('');shell(`${titlebar('CAREER RECORD','OBJECTIVES')}<main class="objectives-page"><header class="career-summary"><span><small>CREDITS</small><b>${save.coins.toLocaleString()}</b></span><span><small>RUNS</small><b>${save.stats.runs}</b></span><span><small>VICTORIES</small><b>${save.stats.victories}</b></span><span><small>HOSTILES</small><b>${save.stats.kills.toLocaleString()}</b></span><span><small>BOSSES</small><b>${save.stats.bosses}</b></span></header><section><div class="section-heading"><div><small>PERMANENT RECORDS</small><h2>ACHIEVEMENTS</h2></div><b>${save.unlockedAchievements.length} / ${achievements.length}</b></div><div class="objective-grid">${achievementCards}</div></section><section><div class="section-heading"><div><small>CLAIMABLE CONTRACTS</small><h2>CHALLENGES</h2></div></div><div class="objective-grid">${challengeCards}</div></section></main>`,'archive objectives');navBack(showMenu);document.querySelectorAll<HTMLButtonElement>('[data-claim]').forEach(button=>button.onclick=()=>{const challenge=challenges.find(c=>c.id===button.dataset.claim);if(!challenge||careerProgress(challenge.stat)<challenge.target||save.claimedChallenges.includes(challenge.id))return;save.claimedChallenges.push(challenge.id);save.coins+=challenge.reward;writeSave(save);showObjectives()})}

type AlmanacCategory='characters'|'weapons'|'cards'|'enemies'|'bosses'|'stages';
type AlmanacEntry={id:string;name:string;kicker:string;color:string;summary:string;facts:Array<[string,string]>;notes:string[]};
const enemyNotes:Record<string,string>={Swarm:'Advances directly in dense groups.',Runner:'Fast flanker with low durability.',Ranged:'Maintains distance and launches slow hostile orbs.',Tank:'Slow, resilient, and dangerous on contact.',Guardian:'Uses a reinforced front to resist direct fire.',Bonus:'Flees combat and drops increased rewards.',Hazard:'Contaminates the arena with damaging zones.',Artillery:'Launches long-range missiles from behind the wave.',Divider:'Splits into two lesser hostiles when destroyed.',Teleporter:'Repositions behind the operative before attacking.'};
function almanacEntries(category:AlmanacCategory):AlmanacEntry[]{
 if(category==='characters')return characters.map(c=>({id:c.id,name:c.name,kicker:c.role,color:c.color,summary:`${c.skill.name}: ${c.skill.description}`,facts:[['STARTING WEAPON',c.weapon.replaceAll('-',' ')],['PASSIVE',c.passive],['HP',String(c.stats.hp)],['MOVE SPEED',String(c.stats.moveSpeed)]],notes:c.stars.map((star,i)=>`${i+2}★ ${star}`)}));
 if(category==='weapons')return weapons.map(w=>({id:w.id,name:w.name,kicker:`${w.type} armament`,color:w.color,summary:`A ${w.melee?'close-range':'projectile'} weapon with built-in ${w.perk}.`,facts:[['DAMAGE',String(w.damage)],['FIRE RATE',`${w.fireRate}/s`],['PROJECTILE SPEED',String(w.speed)],['STATUS',w.status||'None']],notes:[`Built-in perk: ${w.perk}.`,`Weapon upgrades improve damage, fire rate, projectile speed, and the built-in perk rank.`]}));
 if(category==='cards'){const cardEntries=[...relics.map(c=>({...c,family:'STIGMATA'})),...classes.map(c=>({...c,family:'CLASS'}))].map(c=>({id:c.id,name:c.name,kicker:c.family,color:cardHue(c.tag),summary:c.description,facts:[['TAG',c.tags.join(' + ')],['MAX RANK','3★']] as Array<[string,string]>,notes:c.values.map((_:any,i:number)=>`${i+1}★ ${cardEffectCopy(c,i)}`)}));const perkEntries=perks.map(p=>({id:p.id,name:p.name,kicker:'WEAPON PERK',color:cardHue(p.tag),summary:'A stackable modifier applied to both equipped weapons.',facts:[['TAG',p.tag],['MAX RANK','3★']] as Array<[string,string]>,notes:p.effects.map((effect:string,i:number)=>`${i+1}★ ${effect}`)}));return[...cardEntries,...perkEntries]}
 if(category==='enemies')return enemies.map(e=>({id:e.id,name:e.name,kicker:`THREAT ${e.threat} · ${e.role}`,color:e.color,summary:enemyNotes[e.role]||'A hostile breach-form.',facts:[['BASE HP',String(e.hp)],['ATTACK',String(e.atk)],['MOVE SPEED',String(e.speed)],['APPEARS',`${e.appearsAfter}s`]],notes:[`Arena shape: ${e.shape}.`,`Spawn weight: ${e.spawnWeight}.`]}));
 if(category==='bosses')return bosses.map(b=>({id:b.id,name:b.name,kicker:`${b.kind.toUpperCase()} BOSS`,color:b.color,summary:b.trait,facts:[['ATTACK CYCLE',`${b.cooldown}s`],['ARMOR',b.armor?`${Math.round(b.armor*100)}%`:'None'],['REGEN',b.regen?`${(b.regen*100).toFixed(2)}%/s`:'None'],['PATTERNS',String(b.patterns.length)]],notes:b.patterns.map((p:any)=>`${p.name} · ${p.type.toUpperCase()}`)}));
 return stages.map((s,i)=>({id:s.id,name:s.name,kicker:s.endless?'ENDLESS OPERATION':`STAGE ${i+1}`,color:s.primary,summary:s.subtitle,facts:[['THEME',s.theme],['SCALING',s.endless?'1.15× each minute':`${s.mult}× base`],['DURATION',s.endless?'Unbounded':'09:00'],['UNLOCK',i===0?'Available':`Clear stage ${i}`]],notes:s.bosses.map((id:string)=>bosses.find(b=>b.id===id)?.name||id.replaceAll('-',' '))}))
}
function showAlmanac(category:AlmanacCategory='characters',selectedId=''){const categories:AlmanacCategory[]=['characters','weapons','cards','enemies','bosses','stages'],entries=almanacEntries(category),selected=entries.find(e=>e.id===selectedId)||entries[0];shell(`${titlebar('FIELD DATABASE','ALMANAC')}<main class="almanac-page"><nav class="almanac-tabs">${categories.map(name=>`<button data-almanac-tab="${name}" class="${name===category?'active':''}">${name}<small>${almanacEntries(name).length}</small></button>`).join('')}</nav><section class="almanac-browser"><div class="almanac-list">${entries.map(entry=>`<button data-entry="${entry.id}" class="${entry.id===selected.id?'active':''}" style="--entry-color:${entry.color}"><i></i><span><small>${entry.kicker}</small><b>${entry.name}</b></span></button>`).join('')}</div><article class="almanac-detail" style="--entry-color:${selected.color}"><header><small>${selected.kicker}</small><h2>${selected.name}</h2><p>${selected.summary}</p></header><div class="almanac-facts">${selected.facts.map(([label,value])=>`<span><small>${label}</small><b>${value}</b></span>`).join('')}</div><section><small>FIELD NOTES</small>${selected.notes.map(note=>`<p>${note}</p>`).join('')}</section></article></section></main>`,'archive almanac');navBack(showMenu);document.querySelectorAll<HTMLButtonElement>('[data-almanac-tab]').forEach(button=>button.onclick=()=>showAlmanac(button.dataset.almanacTab as AlmanacCategory));document.querySelectorAll<HTMLButtonElement>('[data-entry]').forEach(button=>button.onclick=()=>showAlmanac(category,button.dataset.entry))}

const renderRunResults=showResults;
// The game callback captures this module binding, so decorate it after the
// original renderer is declared while preserving its existing result UI.
// @ts-expect-error Function declarations are mutable JavaScript bindings.
showResults=(stats:RunStats)=>{const before=new Set(save.unlockedAchievements);save.stats.runs++;save.stats.victories+=Number(stats.victory);save.stats.kills+=stats.kills;save.stats.bosses+=stats.bosses;save.stats.coinsCollected+=stats.coinsCollected;save.stats.timePlayed+=Math.floor(stats.time);save.stats.highestLevel=Math.max(save.stats.highestLevel,stats.level);save.stats.cardsPicked+=stats.cardsPicked;renderRunResults(stats);syncAchievements();writeSave(save);const unlocked=achievements.filter(a=>!before.has(a.id)&&save.unlockedAchievements.includes(a.id));if(unlocked.length){const results=document.querySelector('.results');results?.insertAdjacentHTML('beforeend',`<aside class="achievement-unlock"><small>ACHIEVEMENT UNLOCKED</small><b>${unlocked.map(a=>a.name).join(' · ')}</b><span>Rewards added to career credits</span></aside>`)}}
